     ("sin 75° nechaga teng?", "(√6 + √2)/4", "(√6 − √2)/4", "√3/2", "1/2"),
     ("cos 15° nechaga teng?", "(√6 + √2)/4", "(√6 − √2)/4", "1/2", "√3/4"),
     ("sin 15° nechaga teng?", "(√6 − √2)/4", "(√6 + √2)/4", "√2/4", "1/4"),
     ("cos 2α formulalaridan biri qaysi?", "2cos²α − 1", "2cos²α + 1", "cos²α + sin²α", "1 − 2cos²α"),
